class NomGrupoEscala extends BaseNomGrupoEscala {

	/**
     * Obtener un listado de los datos de los grupos escala.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los grupos escala.
     */
    public static function obtenerListadoGruposEscala($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de grupos escala en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomGrupoEscala')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray(): 
        $query->from('NomGrupoEscala')
                ->fetchArray();
        return $result;
    }
	
	/**
     * Obtener todos los grupos escala.
     * 
     * @return array    Listado de los datos de los grupos escala.
     */
	public static function obtenerTodosGruposEscala(){
		//Devolviendo el listado de grupos escala en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomGrupoEscala')
                ->fetchArray();
	}
	
     /**
     * Obtener la cantidad total de grupos escala.
     * 
     * @return int      Cantidad total de grupos escala.
     */
    public static function obtenerCantidadTotalGruposEscala() {

        //Devolviendo la cantidad total de grupos escala.
        return Doctrine_Query::create()->select('COUNT(idgrupoescala) AS cantidad')
                        ->from('NomGrupoEscala')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el grupo escala dado el identificador.
     * 
     * @param int $idgrupoescala    Identificador del grupo escala.
     * @return NomGrupoEscala   Objeto grupo escala (clase del dominio).
     */
    public static function obtenerObjGrupoEscalaDadoId($idgrupoescala) {

        return Doctrine::getTable('NomGrupoEscala')->find($idgrupoescala);

    }


    public static function obtenerObjGrupoEscala($idgrupoescala) {


        return Doctrine_Query::create()
            ->from('NomGrupoEscala a')
            ->where("a.idgrupoescala = $idgrupoescala")
            ->fetchArray();
}
	
	/**
     * Obtener si existe un grupo escala a partir de la denominaci�n.
     * 
	 * @param int $idgrupoesc    	Identificador del grupo escala.
     * @param string $denom    	 	Denominaci�n del grupo escala.
	 *
     * @return boolean    			Si existe el grupo escala.
     */
    public static function existeGrupoEscala($idgrupoesc, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idgrupoescala) AS cantidad')
                        ->from('NomGrupoEscala')
						->where("denominacion ilike ?", $denom);
		if($idgrupoesc){
			$query->addWhere('idgrupoescala <> ?', $idgrupoesc);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	
	
	
	
	
	
	
	
	
	
	/**********************************VER DE AQUI *******************************************/
    public static function existeDenominacionGrupoEscala($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomGrupoEscala p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idgrupoescala = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomGrupoEscala')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idgrupoescala)) {
                $query->andWhere("idgrupoescala <> ?", $idgrupoescala);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }
}
